  const readCommands: import('../src/lib/ipc/client').SetRead[] = [];
  const retryCommands: import('../src/lib/ipc/client').RetryOperation[] = [];
  const client = decorateClient(inner, {
    listConversations: () => {
      list += 1;
      return inner.listConversations();
